        // So we distribute the k to the even-positioned items
        // The even-positioned items are at indices 1, 3, 5, ... (0-based)
        for (int i = 1; i < n; i += 2) {
            if (k <= 0) break;
            // We can increase this item as much as possible
            // But we need to ensure that it remains the largest in its position
            // So we can increase it by any amount, but we need to distribute k
            // So we can increase it by k
            a[i] += k;
            k = 0;
        }
        // Now compute the difference
        long long A = 0, B = 0;
        for (int i = 0; i < n; ++i) {
            if (i % 2 == 0) {
                A += a[i];
            } else {
                B += a[i];
            }
        }
        cout << A - B << endl;
    }
    return 0;
}

